listeners.registration:
this.panel.addEventListener('click', event => {
            const tab = event.target.closest('[data-scene-section]');
            if (!tab) return;
            this.section = tab.dataset.sceneSection;
            this.signature = '';
            void this.render(this.entity, this.record, this.records);
        })

this.category.addEventListener('change', () => {
            // Reuse the workspace navigation queue and its captured action identity.
            rail.querySelector(`[data-workspace-action="${this.category.value}"]`)?.click();
        })

control.addEventListener('keydown', event => {
                if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); control.click(); }
            })

search.addEventListener('input', () => {
        const query = search.value.toLocaleLowerCase();
        for (const option of list.children) option.hidden = !option.textContent.toLocaleLowerCase().includes(query);
    })

list.addEventListener('change', () => {
        const selected = list.querySelectorAll('input:checked').length;
        count.textContent = `${selected} characters selected`;
        create.disabled = selected < 2;
    })

document.addEventListener('click', event => {
        const target = event.target instanceof Element ? event.target.closest('[data-workspace-action], [data-service-destination]') : null;
        if (!target) return;
        event.preventDefault();
        if (target.disabled) return;
        const action = target.dataset.workspaceAction || target.dataset.serviceDestination;
        const startsStory = ['start-story', 'start-current-story'].includes(action);
        if (startsStory) {
            if (state.starting || event.detail > 1) return;
            state.starting = true;
            refreshWorkspace();
        }
        const command = document.getElementById('workspace-command');
        if (command.open && action !== 'close-search') command.close();
        closeActionMenus();
        const showError = error => { console.error('Workspace action failed', error); toastr.error(error.message || 'This action could not finish. Try again.'); };
        if (['generate-scene-image', 'generate-image', 'generate-custom-image'].includes(action)) {
            if (isGenerating()) { showError(new Error('Wait for the reply to finish before illustrating this scene.')); return; }
            void creativeTools.generate(action === 'generate-scene-image' ? 'scene' : action === 'generate-image' ? target.dataset.imagePrompt : document.getElementById('workspace-image-prompt').value).catch(showError);
        } else {
            // A page may reconcile while this command waits. Capture identity at click time.
            const request = { dataset: { ...target.dataset }, element: target };
            navigationQueue = navigationQueue.then(() => handleAction(action, request)).catch(showError).finally(() => {
                if (startsStory) { state.starting = false; refreshWorkspace(); }
            });
        }
    })

document.addEventListener('input', event => {
        if (event.target.id === 'workspace-view-search') { state.query = event.target.value; renderPage(); }
    })

document.addEventListener('change', event => {
        const target = event.target;
        if (!(target instanceof HTMLInputElement)) return;
        if (['tts_enabled', 'sd_enabled'].includes(target.id)) refreshWorkspace();
    })

document.getElementById('workspace-command').addEventListener('keydown', event => {
        const buttons = [...document.querySelectorAll('#workspace-command-results button')];
        const index = buttons.indexOf(document.activeElement);
        if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
            event.preventDefault();
            buttons[(index + (event.key === 'ArrowDown' ? 1 : -1) + buttons.length) % buttons.length]?.focus();
        } else if (event.key === 'Enter' && event.target.id === 'workspace-command-input') { event.preventDefault(); buttons[0]?.click(); }
    })

document.addEventListener('keydown', event => {
        if (!document.body.classList.contains('workspace-ui') || event.isComposing) return;
        if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k' && !document.querySelector('dialog[open]')) { event.preventDefault(); openSearch(); } else if (event.key === 'Escape' && !document.querySelector('dialog[open]')) {
            if (hasNativeEscapeTarget({ includeGeneration: false })) return;
            const nativeMenu = openNativeActionMenus()[0];
            if (nativeMenu) {
                event.preventDefault(); event.stopImmediatePropagation();
                const trigger = document.getElementById(nativeMenu[1]);
                trigger.click(); trigger.focus();
                return;
            }
            if (closeActionMenus(null, true)) { event.preventDefault(); event.stopImmediatePropagation(); return; }
            if (document.body.classList.contains('workspace-nav-open')) {
                event.preventDefault(); event.stopImmediatePropagation(); setMobileNavigation(false); document.getElementById('workspace-menu').focus();
            } else if (settingsPanel.active) {
                event.preventDefault(); event.stopImmediatePropagation(); void closeDrawers().then(() => { refreshWorkspace(); focusContent(); });
            } else if (!settingsPanel.active && document.body.classList.contains('workspace-inspecting')) {
                event.preventDefault(); event.stopImmediatePropagation(); document.body.classList.remove('workspace-inspecting'); refreshWorkspace(); document.getElementById('workspace-header-portrait').focus();
            }
        } else if (event.key === 'Tab' && (document.body.classList.contains('workspace-nav-open') || (document.body.classList.contains('workspace-inspecting') && matchMedia('(max-width: 900px)').matches))) {
            const selector = document.body.classList.contains('workspace-nav-open') ? '#workspace-sidebar a, #workspace-sidebar button' : '#workspace-scene-info button:not(:disabled), #workspace-scene-info summary, #workspace-scene-info input:not(:disabled), #workspace-scene-info select:not(:disabled), #workspace-scene-info textarea:not(:disabled), #workspace-scene-info a[href], #workspace-scene-info pre';
            const controls = [...document.querySelectorAll(selector)].filter(control => control.getClientRects().length && (control.tagName !== 'PRE' || control.scrollHeight > control.clientHeight));
            if (event.shiftKey && document.activeElement === controls[0]) { event.preventDefault(); controls.at(-1)?.focus(); } else if (!event.shiftKey && document.activeElement === controls.at(-1)) { event.preventDefault(); controls[0]?.focus(); }
        }
    }, { capture: true })

this.url.addEventListener('input', () => {
            this.request?.abort();
            this.voiceRequest?.abort();
            this.data = null;
            this.attempted = false;
            this.results.replaceChildren();
            this.clearRows();
            this.status.textContent = 'Verify this address to refresh its available services.';
            this.verify.disabled = false;
        })

document.addEventListener('change', event => {
            if (event.target.closest('.service-connection-row')) return;
            queueMicrotask(() => this.syncSelections());
        })

action.addEventListener('click', async () => {
            controls.pending = true;
            action.disabled = true;
            select.disabled = true;
            if (controls.voice) controls.voice.disabled = true;
            status.textContent = 'Applying connection…';
            try {
                await apply(select.value);
                controls.applied = JSON.stringify(this.selection(id));
                status.textContent = 'Saved. This service uses the selected model. Test it in your story when ready.';
                this.targets.get(id).native.open = Boolean(this.advanced);
                this.updateContext();
                this.updateWriter();
            } catch (error) {
                status.textContent = `${error.message} Retry or open the provider settings.`;
            } finally {
                controls.pending = false;
                if (row.isConnected) {
                    action.disabled = id !== 'writer' && !select.value;
                    select.disabled = !service?.models?.length;
                    if (controls.voice) controls.voice.disabled = !controls.voices?.length;
                }
            }
        })

container.addEventListener('focusout', (e) => {
        setTimeout(() => {
            const focusedElement = document.activeElement;
            if (!container.contains(focusedElement)) {
                container.scrollTop = 0;
                container.scrollLeft = 0;
            }
        }, 0);
    })

upload.addEventListener('change', async () => {
            const file = upload.files?.[0];
            if (!file) return;
            if (this.active) { this.fileStatus.textContent = 'Finish or cancel the current dictation first.'; upload.value = ''; return; }
            if (!getCurrentChatId()) { this.show('Open a story before transcribing audio.'); upload.value = ''; return; }
            const sequence = ++this.sequence;
            this.active = true;
            this.update();
            try {
                await this.transcribe(file, sequence, storyIdentity());
            } catch (error) {
                if (sequence === this.sequence) this.show(error.message);
            } finally {
                if (sequence === this.sequence) {
                    this.active = false;
                    upload.value = '';
                    this.update();
                }
            }
        })

document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'hidden' && (this.stream || this.microphonePending)) this.cancel('Recording stopped when the tab was hidden. Retry dictation when ready.');
        })

document.addEventListener('freeze', () => {
            if (this.stream || this.microphonePending) this.cancel('Recording stopped when the tab was suspended. Retry dictation when ready.');
        })
